71	function readInput(state: ClaimState, input: ClaimTickInput): { players: Map<string, ClaimPlayer>; reservedBy: Map<string, ClaimEncounter> } {
72	  requireInteger(input.tick, "tick");
73	  if (input.tick !== state.tick + 1) throw new RangeError(`expected tick ${state.tick + 1}, got ${input.tick}`);
