85	  const reservedBy = new Map<string, ClaimEncounter>();
86	  for (const encounter of input.encounters) {
87	    requireId(encounter.id, "encounter id");
88	    if (encounterIds.has(encounter.id)) throw new RangeError(`encounter ${encounter.id} appears twice`);
89	    encounterIds.add(encounter.id);
90	    const [a, b] = encounter.playerIds;
91	    requireId(a, `encounter ${encounter.id} player`);
92	    requireId(b, `encounter ${encounter.id} player`);
93	    if (a === b) throw new RangeError(`encounter ${encounter.id} reserves ${a} twice`);
94	    for (const id of [a, b]) {
95	      if (reservedBy.has(id)) throw new RangeError(`player ${id} is in two encounters`);
96	      reservedBy.set(id, encounter);
97	    }
98	  }
