102	/**
103	 * One world tick of §5's claim rules, in a fixed order: (1) accepted encounter reservations interrupt the channel,
104	 * (2) the active channel breaks or advances, (3) with no channel active the best eligible starter begins one,
105	 * (4) a channel that has run `channelTicks` completes, and (5) on the deadline tick a match without a winner ends with
106	 * none. Players and encounters are read as sets, so their order in the input never matters. Once the match has a
107	 * result, every later input is ignored and the state is returned unchanged. The input state is never mutated.
108	 */
109	export function stepClaim(config: ClaimConfig, state: ClaimState, input: ClaimTickInput): ClaimStepResult {
110	  if (state.result !== null) return { state, events: [] };
111	  const { players, reservedBy } = readInput(state, input);
112	  const tick = input.tick;
113	  const events: ClaimEvent[] = [];
114	  let channel = state.channel;
115	  const interrupt = (active: ClaimChannel, reason: ClaimInterruptReason) =>
116	    events.push({ kind: "claim-interrupted", tick, playerId: active.playerId, reason, progress: active.progress });
117	
118	  // 1. Reservations first (§5): a duel accepted on the tick a claim would complete still stops it.
119	  if (channel !== null && reservedBy.has(channel.playerId)) {
120	    interrupt(channel, "duel");
121	    channel = null;
122	  }
123	
124	  // 2. The active channel.
125	  if (channel !== null) {
126	    const reason = channelBreak(channel, players.get(channel.playerId));
127	    if (reason === null) {
128	      channel = { ...channel, progress: channel.progress + 1 };
129	    } else {
130	      interrupt(channel, reason);
131	      channel = null;
132	    }
133	  }
134	
135	  // 3. One channel at a time: others wait. Simultaneous starters: the closest to the claim point, then the lowest id.
136	  if (channel === null) {
137	    let best: { player: ClaimPlayer; distance: number } | null = null;
138	    for (const player of players.values()) {
139	      if (!canStartClaim(config, player, reservedBy.has(player.id))) continue;
140	      const distance = claimDistanceSquared(config, player.x, player.y);
141	      if (best === null || distance < best.distance || (distance === best.distance && compareIds(player.id, best.player.id) < 0)) {
142	        best = { player, distance };
143	      }
144	    }
145	    if (best !== null) {
146	      const { id, x, y } = best.player;
147	      if (best.player.protected) events.push({ kind: "protection-ended", tick, playerId: id });
148	      events.push({ kind: "claim-started", tick, playerId: id });
149	      channel = { playerId: id, startTick: tick, x, y, progress: 0 };
150	    }
151	  }
152	
153	  // 4. Completion commits the winner; it comes before the deadline, so a claim completing on the deadline tick wins.
154	  let result: ClaimResult | null = null;
155	  if (channel !== null && channel.progress >= config.channelTicks) {
156	    events.push({ kind: "claim-completed", tick, playerId: channel.playerId });
157	    result = { reason: "claim", winner: channel.playerId, tick };
158	    channel = null;
159	  }
160	
161	  // 5. The deadline: no winner, and an unfinished channel is cancelled.
162	  if (result === null && tick >= config.deadlineTick) {
163	    if (channel !== null) interrupt(channel, "deadline");
164	    channel = null;
165	    result = { reason: "deadline", winner: null, tick };
166	  }
167	
168	  // The match is over: outcomes freeze, so every duel still reserved or running ends without theft.
169	  if (result !== null) {
170	    const encounters = [...input.encounters].sort((a, b) => compareIds(a.id, b.id));
171	    for (const encounter of encounters) {
172	      // In id order, so the event never echoes the order the caller listed the players in.
173	      const playerIds = [...encounter.playerIds].sort(compareIds) as [string, string];
174	      events.push({ kind: "duel-ended-without-theft", tick, encounterId: encounter.id, playerIds });
175	    }
176	    events.push({ kind: "match-ended", tick, reason: result.reason, winner: result.winner });
177	  }
178	
179	  return { state: { tick, channel, result }, events };
180	}
181	
182	export interface ClaimReplay {
183	  readonly state: ClaimState;
184	  readonly events: readonly ClaimEvent[];
185	  readonly hash: string;
186	}
187	
188	/** Steps a sequence of ticks from a state, collecting every event; `hash` is the final state's `hashState`. */
189	export function replayClaim(config: ClaimConfig, state: ClaimState, inputs: readonly ClaimTickInput[]): ClaimReplay {
190	  let current = state;
191	  const events: ClaimEvent[] = [];
192	  for (const input of inputs) {
193	    const stepped = stepClaim(config, current, input);
194	    current = stepped.state;
195	    events.push(...stepped.events);
196	  }
197	  return { state: current, events, hash: hashState(current) };
198	}
